+    public static Expr tailOf(Expr e) {
+        while (true) {
+            if (e instanceof Do && ((Do) e).getFronts().size() == 1) e = ((Do) e).getFronts().get(0);
+            else if (e instanceof Block && !((Block) e).getExprs().isEmpty()) {
