337      <T extends Expr> List<FValue> evalExprListParallel(List<T> exprs) {
338          // Added some special-case code to avoid explosion of TupleTasks.
339          int sz = exprs.size();
340          ArrayList<FValue> resList = new ArrayList<FValue>(sz);
341          ArrayList<TupleTask> TupleTasks = new ArrayList<TupleTask>(sz);
342          if (sz < 2 || !TupleTask.worthSpawning()) {
343              evalExprList(exprs, resList);
344          } else {
345              for (Expr expr : exprs)
346              // We want to add things to the front of the list.
347              {
348                  TupleTasks.add(0, new TupleTask(expr, this));
349              }
350  
351              BaseTask currentTask = FortressTaskRunner.getTask();
352              TupleTask.invokeAll(TupleTasks);
353              FortressTaskRunner.setCurrentTask(currentTask);
354  
355              for (TupleTask task : TupleTasks) {
356                  resList.add(0, task.getResOrException());
357              }
358          }
359  
360          if (resList.size() != exprs.size()) bug(
361                  "We should have the same number of results as we did exprs resList = " + resList + " exprs = " + exprs);
362          return resList;
363      }

